fn surface()->Surface{Surface{availability:Availability::NotRequested,row_count:None,source:None,error_code:None,http_status:None,retry_after_ms:None}}
struct Fixture{census:Census,canonical:Receipt,certs:Vec<SettlementCertificate>,trusted:BTreeSet<String>,rules:Vec<Receipt>,books:BTreeMap<String,Book>,policy:Policy,capital:Capital}
impl Fixture{
 fn analyze(&self,positions:&[OwnedPosition])->Analysis{analyze(&self.census,&self.canonical,&Certificates{values:&self.certs,trusted_sha256:&self.trusted,rule_receipts:&self.rules},&self.books,positions,&self.capital,&self.policy)}
 fn approve(&mut self){self.trusted=self.certs.iter().map(|c|certificate_sha256(c).unwrap()).collect();}
}
fn fixture(n:usize,exhaustive:bool)->Fixture{
 let scope=Scope{tournament_id:T.into(),tournament_slug:"midterm-elections".into(),exchanges:(0..n).map(|i|((101+i).to_string(),(201+i).to_string())).collect()};
 let nodes:Vec<_>=(0..n).map(|i|json!({"exchangeId":(101+i).to_string(),"marketId":(201+i).to_string(),"marketTitle":"not a proof","outcome":"YES","currentPrice":null,"role":"member","contractId":(301+i).to_string()})).collect();
 let canonical=receipt(format!("/relationships?tournamentId={T}&depth=4"),json!({"data":[{"id":R,"type":"mutually_exclusive","source":"admin_tagged","status":"active","label":null,"reason":null,"isExhaustive":exhaustive,"expression":null,"nodes":nodes,"direction":{"kind":"symmetric","fromExchangeIds":[],"toExchangeIds":[],"description":"price metadata"},"constraint":{"description":"not a settlement certificate","priceRule":"sum <= 1","boundSemantics":"price","evaluationEndpoint":"/relationships/constraints"},"createdAt":AT,"updatedAt":AT,"version":2}],"pagination":{"limit":200,"hasMore":false,"nextCursor":null}}));
 let list=relationships::parse_list(&canonical.data,&scope).unwrap();
 let rules:Vec<_>=(0..n).map(|i|receipt(format!("/markets/{}/nodes",201+i),json!({"market_id":(201+i).to_string(),"root":{"node_id":(301+i).to_string(),"node_type":"contract","contract_id":(301+i).to_string(),"contract_type":"Election Outcome","title":"Synthetic reviewed fixture contract","settlement_date":null,"settled_with":null,"contract_details":null}}))).collect();
 let cert=SettlementCertificate{version:1,tournament_id:T.into(),relationship_id:R.into(),relationship_version:2,canonical_relationship_sha256:canonical_relationship_sha256(&list.data[0]).unwrap(),relationship_receipt_sha256:receipt_sha256(&canonical).unwrap(),issued_at_ms:now(),expires_at_ms:now()+60_000,verifier_id:"fixture-only-reviewed-rules".into(),logic:CertifiedLogic::MutuallyExclusive{exhaustive},contracts:(0..n).map(|i|ContractCertificate{exchange_id:(101+i).to_string(),market_id:(201+i).to_string(),contract_id:(301+i).to_string(),canonical_outcome:"YES".into(),rule_receipt_sha256:receipt_sha256(&rules[i]).unwrap(),rule_endpoint:rules[i].endpoint.clone(),rule_data_sha256:None,ordinary_yes_payout:"1".into(),ordinary_no_payout:"0".into(),ordinary_no_yes_payout:"0".into(),ordinary_no_no_payout:"1".into(),terminal_rules_complete:true,exceptions:vec![]}).collect()};
 let scope_sha256=format!("{:x}",Sha256::digest(serde_json::to_vec(&scope).unwrap()));
 let census=Census{report:CensusReport{version:1,started_at_ms:now(),completed_at_ms:now(),tournament_id:T.into(),scope_sha256,relationships:Surface{availability:Availability::Available,row_count:Some(1),source:Some(SourceEvidence{receipt_sha256:receipt_sha256(&canonical).unwrap(),private_file:"fixture-private.json".into(),request_started_at:AT.into(),received_at:AT.into(),status:200}),error_code:None,http_status:Some(200),retry_after_ms:None},constraints:surface(),collateral:surface(),account:surface(),graphs:BTreeMap::new(),active_relationship_count:1,exhaustive_relationship_count:usize::from(exhaustive),known_floor_component_count:0,unknown_floor_component_count:0,feed_complete:false,transport_guard_observed:false,execution_authority:false},cache:CensusCache{scope,relationships:Some(list),constraints:None,collateral:None,buying_power:None,graphs:BTreeMap::new(),private_evidence_directory:PathBuf::from("fixture-unused")}};
 let books=(0..n).map(|i|{let e=(101+i).to_string();(e.clone(),Book{exchange_id:e,source:Source{sha256:"b".repeat(64),received_ms:now()},observed_ms:now(),yes_asks:level(if n==3{300_000}else{600_000}),no_asks:level(if n==3{800_000}else if i==0{450_000}else{505_000}),yes_bids:level(290_000),no_bids:level(400_000)})}).collect();
 let policy=Policy{now_ms:now(),max_relationship_age_ms:30_000,max_rule_age_ms:3_600_000,max_book_age_ms:3000,max_book_skew_ms:1000,entry_fee_per_share_per_leg:0,buffer_per_share:5000,minimum_surplus:1,maximum_quantity:100,quantities:vec![10],maximum_retained_candidates:16};
 let capital=Capital{gross_account_cash:100*UNIT,attributed_bank_cash:20*UNIT,reserved_cash:0,maximum_committed_remaining:20*UNIT,package_cost_cap:20*UNIT,orphan_cash_loss_cap:20*UNIT};
 let mut f=Fixture{census,canonical,certs:vec![cert],trusted:BTreeSet::new(),rules,books,policy,capital};f.approve();f
}
fn blocked(a:&Analysis,code:&str){assert_eq!(a.public.blocked_reason_counts.get(code),Some(&1));assert!(a.candidates.is_empty());assert!(!a.public.execution_authority);}

struct AdmissionBank{bank:moloch_replay::session::Session,activation:moloch_live_runtime::authority::Activation,path:PathBuf}
impl Drop for AdmissionBank{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.path);}}
fn admission_bank(f:&Fixture)->AdmissionBank{admission_bank_mode(f,false)}
fn admission_bank_mode(f:&Fixture,quoted:bool)->AdmissionBank{
 let path=std::env::temp_dir().join(format!("package-admission-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));
 let end=now()+60_000;let until=chrono::DateTime::from_timestamp_millis(end as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true);
 let policy=json!({"initialCash":"1000.000000","maximumCommitted":"1000.000000","maximumMarketCost":"100.000000","quantity":100,"maximumMarkets":3,"minimumSpreadTicks":if quoted{2}else{200},"entryStopAt":until});
 let seed=json!({"runId":"package-fixture","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":AT});
 let mut bank=moloch_replay::session::Session::open_live(&path,&policy,&seed).unwrap();
 for(index,(ex,b))in f.books.iter().enumerate(){
  let bids:Vec<_>=b.no_asks.iter().map(|l|json!({"price":moloch_replay::money(UNIT-l.price),"quantity":l.quantity})).collect();
  let asks:Vec<_>=b.yes_asks.iter().map(|l|json!({"price":moloch_replay::money(l.price),"quantity":l.quantity})).collect();
  let event=json!({"type":"book","receivedAt":AT,"book":{"tournamentId":T,"marketId":f.census.cache.scope.exchanges[ex],"exchangeId":ex,"sequence":"1","requestStartedAt":AT,"sourceAt":AT,"receivedAt":AT,"bids":bids,"asks":asks}});
  bank.accept("fixture-book",index as u64+1,&event).unwrap();
 }
 let activation=moloch_live_runtime::authority::Activation{run_id:"package-fixture".into(),entry_until_ms:end,maximum_committed:"1000.000000".into(),maximum_market_cost:"100.000000".into(),maximum_quantity:100,tournament_id:T.into(),tournament_slug:"midterm-elections".into(),binary_sha256:"b".repeat(64)};
 AdmissionBank{bank,activation,path}
}
fn admit_fixture(f:&Fixture,b:&AdmissionBank)->moloch_live_runtime::feedback::Result<Option<moloch_live_runtime::package_admission::Admission>>{
 moloch_live_runtime::package_admission::admit(&b.bank,&b.activation,&f.census,&f.canonical,&moloch_live_runtime::relationship_strategy::Certificates{values:&f.certs,trusted_sha256:&f.trusted,rule_receipts:&f.rules},1000*UNIT,&f.policy,b.activation.entry_until_ms)
}

use moloch_live_runtime::{relationship_strategy,authority,feedback,package_admission,daily_windows,inventory};
use moloch_live_runtime::package_portfolio;
use serde_json::Value;
fn certified(f:&Fixture)->CertifiedComponent{certified_component(&f.census,&f.canonical,&Certificates{values:&f.certs,trusted_sha256:&f.trusted,rule_receipts:&f.rules},R,&f.policy).unwrap()}
fn held_bank(f:&Fixture,side:&str,n:u64)->AdmissionBank{let mut b=admission_bank(f);let signed=if side=="NO"{-(n as i64)}else{n as i64};let r=receipt(format!("/tournaments/{}/portfolio/positions",f.census.cache.scope.tournament_slug),json!({"positions":[{"exchangeId":"101","marketId":"201","quantity":signed,"costBasis":n as f64*0.2,"lots":[{"lotId":"9101","quantity":n,"side":side,"entryPrice":0.2,"openedAt":AT}]}]}));let e=inventory::adoption(&r,b.bank.engine(),T,&f.census.cache.scope.tournament_slug,&f.census.cache.scope.exchanges,AT).unwrap();b.bank.accept("adoption",1,&e).unwrap();
 // Real native retirement of original never-submitted quotes, not a fabricated
 // flat order view. Keep the original timestamp and source causal ordering.
 for (i,q) in b.bank.engine().order_records().into_iter().filter(|q|q["retired"]==false).enumerate(){
 let e=json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"confirmedNetworkAttempts":0,"receiptHash":"e".repeat(64),"receivedAt":AT});
 b.bank.accept("fixture-retire",i as u64+1,&e).unwrap();
 }b}
fn counterexample()->Fixture{let mut f=fixture(2,true);f.policy.quantities=vec![5];f.policy.maximum_quantity=5;f.policy.buffer_per_share=0;f.books.get_mut("102").unwrap().no_asks=level(500000);f}
fn complete_real_session_package(f:&Fixture,b:&mut AdmissionBank)->String{let a=admit_fixture(f,b).unwrap().unwrap();let id=a.package_id().to_owned();let mut n=1u64;b.bank.accept("owned-package",n,a.reserve_event()).unwrap();let mut attempt=a.reserve_event().clone();attempt["type"]=json!("live_package_attempt");attempt["receivedAt"]=json!(daily_windows::iso(now()+3000).unwrap());attempt["processedAt"]=attempt["receivedAt"].clone();attempt["requestHash"]=json!("c".repeat(64));attempt["idempotencyKey"]=json!(a.basket().idempotency_key);attempt["bookHashes"]=b.bank.engine().live_package_books().iter().map(|raw|(raw["exchangeId"].as_str().unwrap().to_owned(),json!(format!("{:x}",Sha256::digest(serde_json::to_vec(raw).unwrap()))))).collect::<serde_json::Map<_,_>>().into();n+=1;b.bank.accept("owned-package",n,&attempt).unwrap();for q in b.bank.engine().order_records(){let at=daily_windows::iso(now()+3001).unwrap();let mut e=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"d".repeat(64),"orderId":q["id"],"actualOrderId":format!("90{}",q["id"].as_u64().unwrap()),"exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":q["action"],"quantity":q["quantity"],"price":q["price"],"receivedAt":at});n+=1;b.bank.accept("owned-package",n,&e).unwrap();e["type"]=json!("actual_fill");e["fillId"]=json!(format!("80{}",q["id"].as_u64().unwrap()));e["fee"]=json!("0.000000");e["executedAt"]=e["receivedAt"].clone();n+=1;b.bank.accept("owned-package",n,&e).unwrap();e["type"]=json!("actual_order_terminal");e["filledQuantity"]=q["quantity"].clone();e["fillsComplete"]=json!(true);e["status"]=json!("filled");n+=1;b.bank.accept("owned-package",n,&e).unwrap();}attempt["type"]=json!("live_package_complete");attempt["receivedAt"]=json!(daily_windows::iso(now()+3002).unwrap());attempt["processedAt"]=attempt["receivedAt"].clone();n+=1;b.bank.accept("owned-package",n,&attempt).unwrap();id}
fn profitable_unwind_books(f:&mut Fixture,b:&mut AdmissionBank){f.policy.now_ms=now()+4000;for(index,(ex,_))in f.books.iter().enumerate(){let at=daily_windows::iso(f.policy.now_ms).unwrap();let event=json!({"type":"book","receivedAt":at,"book":{"tournamentId":T,"marketId":f.census.cache.scope.exchanges[ex],"exchangeId":ex,"sequence":"2","requestStartedAt":at,"sourceAt":at,"receivedAt":at,"bids":[{"price":"0.350000","quantity":100}],"asks":[{"price":"0.400000","quantity":100}]}});b.bank.accept("unwind-book",index as u64+1,&event).unwrap();}}
use moloch_live_runtime::package_allocation::*;
fn cash(b:&AdmissionBank)->Receipt{receipt(format!("/account?tournamentId={T}"),json!({"balance":serde_json::from_str::<Value>(&moloch_replay::money(b.bank.engine().wallet.cash)).unwrap(),"availableAdvance":0,"buyingPower":serde_json::from_str::<Value>(&moloch_replay::money(b.bank.engine().wallet.cash)).unwrap()}))}
fn review(f:&Fixture,risk:i128,horizon:Option<u64>,group:Option<&str>)->ReviewedCosts{let input=ReviewInput{certificate_sha256:certificate_sha256(&f.certs[0]).unwrap(),risk_group:"same-reviewed-component".into(),write_cost_units:0,inventory_risk_units:risk,holding_horizon_ms:horizon,comparable_group:group.map(str::to_owned),expires_at_ms:now()+60_000,source_sha256:"e".repeat(64)};let trusted=[ReviewedCosts::digest(&input).unwrap()].into();ReviewedCosts::verify(input,&trusted,now()).unwrap()}
fn variant(f:&Fixture,name:&str)->Fixture{let mut v=counterexample();v.certs[0].verifier_id=name.into();v.books=f.books.clone();v.approve();v}
fn hint(f:&Fixture,b:&AdmissionBank,budget:&Budget,costs:&ReviewedCosts)->ReadHint{ReadHint::scan(&b.bank,&b.activation,&certified(f),&f.policy,budget,costs).unwrap().unwrap()}
#[test]fn actual_source_hint_is_not_reservation_and_full_worst_limit_cost_replaces_average_depth(){let mut f=counterexample();f.books.get_mut("101").unwrap().no_asks=vec![Level{price:450000,quantity:2},Level{price:480000,quantity:100}];let b=admission_bank(&f);let before=b.bank.engine().report().unwrap();let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();let h=hint(&f,&b,&budget,&review(&f,0,None,None));assert_eq!(h.gross_funding(),4_900_000);assert_eq!(h.minimum_incremental_gain(),100000);assert_eq!(b.bank.engine().report().unwrap(),before);assert!(b.bank.engine().package_records().as_array().unwrap().is_empty());}
#[test]fn borrowed_real_plan_positive_statewise_gain_selects_but_held_floor_increase_does_not(){let f=counterexample();let b=admission_bank(&f);let c=certified(&f);let plan=package_portfolio::acquire(&b.bank,&b.activation,&c,1000*UNIT,&f.policy,b.activation.entry_until_ms).unwrap().unwrap();let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();let costs=review(&f,0,None,None);let eligible=Eligible::portfolio(&b.bank,&plan,&budget,&costs,now()).unwrap();let mut fairness = Fairness::new(8).unwrap();let(selected,d)=select_plans(&b.bank,&budget,&mut fairness,vec![eligible],now()).unwrap();assert!(matches!(selected.unwrap().plan(),BorrowedPlan::Portfolio(_)));assert_eq!(d.objective,Some(Objective::CapitalEfficiencyOnly));assert!(!d.execution_authority);let held=held_bank(&f,"NO",5);let hedge=package_portfolio::acquire(&held.bank,&held.activation,&c,1000*UNIT,&f.policy,held.activation.entry_until_ms).unwrap().unwrap();assert!(hedge.minimum_statewise_delta()<0);let budget=Budget::from_receipt(&held.bank,&held.activation,&cash(&held),1,now()).unwrap();assert!(Eligible::portfolio(&held.bank,&hedge,&budget,&costs,now()).is_err());}
#[test]fn genuine_legacy_admission_is_recomputed_against_current_flat_books_and_budget(){let f=counterexample();let mut b=admission_bank(&f);let a=admit_fixture(&f,&b).unwrap().unwrap();let costs=review(&f,0,None,None);let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();let e=Eligible::admission(&b.bank,&a,&budget,&costs,now()).unwrap();assert!(matches!(e.plan(),BorrowedPlan::Admission(_)));b.bank.accept("changed",1,&json!({"type":"tick","receivedAt":AT})).unwrap();assert!(Eligible::admission(&b.bank,&a,&budget,&costs,now()).is_err());}
#[test]fn reviewed_write_risk_costs_remove_positive_looking_but_nonpositive_incremental_value(){let f=counterexample();let b=admission_bank(&f);let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();assert!(ReadHint::scan(&b.bank,&b.activation,&certified(&f),&f.policy,&budget,&review(&f,300000,None,None)).unwrap().is_none());let mut input=ReviewInput{certificate_sha256:certificate_sha256(&f.certs[0]).unwrap(),risk_group:"component".into(),write_cost_units:250000,inventory_risk_units:0,holding_horizon_ms:None,comparable_group:None,expires_at_ms:now()+60000,source_sha256:"a".repeat(64)};assert!(ReviewedCosts::verify(input.clone(),&BTreeSet::new(),now()).is_err());let trust=[ReviewedCosts::digest(&input).unwrap()].into();let cost=ReviewedCosts::verify(input.clone(),&trust,now()).unwrap();assert!(ReadHint::scan(&b.bank,&b.activation,&certified(&f),&f.policy,&budget,&cost).unwrap().is_none());input.inventory_risk_units=-1;let trust=[ReviewedCosts::digest(&input).unwrap()].into();assert!(ReviewedCosts::verify(input,&trust,now()).is_err());}
#[test]fn unknown_horizon_is_capital_efficiency_only_and_mixed_groups_never_mix_time_units(){let f=counterexample();let b=admission_bank(&f);let other=variant(&f,"other-reviewed-source");let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();let mut fair=Fairness::new(8).unwrap();let(_,d)=select_hints(&b.bank,&budget,&mut fair,vec![hint(&f,&b,&budget,&review(&f,10000,Some(1),Some("fast"))),hint(&other,&b,&budget,&review(&other,0,Some(1_000_000),Some("unrelated")))],now()).unwrap();assert_eq!(d.objective,Some(Objective::CapitalEfficiencyOnly));assert_eq!(d.selected_key,Some(format!("{}:buy",certificate_sha256(&other.certs[0]).unwrap())));}
#[test]fn same_comparable_review_group_can_prefer_less_absolute_gain_per_capital_time(){let f=counterexample();let b=admission_bank(&f);let other=variant(&f,"other-reviewed-source");let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();let mut fair=Fairness::new(8).unwrap();let(_,d)=select_hints(&b.bank,&budget,&mut fair,vec![hint(&f,&b,&budget,&review(&f,100000,Some(1000),Some("same"))),hint(&other,&b,&budget,&review(&other,0,Some(10000),Some("same")))],now()).unwrap();assert_eq!(d.objective,Some(Objective::ReviewedCapitalTime{comparable_group:"same".into()}));assert_eq!(d.selected_key,Some(format!("{}:buy",certificate_sha256(&f.certs[0]).unwrap())));}
#[test]fn score_ties_rotate_and_starvation_only_promotes_still_positive_eligible_hints(){let f=counterexample();let b=admission_bank(&f);let other=variant(&f,"other-reviewed-source");let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();let mut fair=Fairness::new(2).unwrap();let mut keys=vec![];for _ in 0..2{let(_,d)=select_hints(&b.bank,&budget,&mut fair,vec![hint(&f,&b,&budget,&review(&f,0,None,None)),hint(&other,&b,&budget,&review(&other,100000,None,None))],now()).unwrap();keys.push(d.selected_key.unwrap());}assert_ne!(keys[0],keys[1]);let zero=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),0,now()).unwrap();let(s,d)=select_hints(&b.bank,&zero,&mut fair,vec![hint(&f,&b,&zero,&review(&f,0,None,None))],now()).unwrap();assert!(s.is_none());assert_eq!(d.deferred.values().next().unwrap(),"shared_write_budget");}
#[test]fn original_cash_scope_clock_null_and_credit_cannot_be_substituted(){let f=counterexample();let b=admission_bank(&f);for mode in ["endpoint","future","old","unknown","contradictory"]{let mut r=cash(&b);match mode{"endpoint"=>r.endpoint="/account?tournamentId=other".into(),"future"=>r.received_at=daily_windows::iso(now()+1).unwrap(),"old"=>r.request_started_at=daily_windows::iso(now()-20001).unwrap(),"unknown"=>{r.data["balance"]=Value::Null;r.data["buyingPower"]=Value::Null;},_=>r.data["balance"]=json!(999)}assert!(Budget::from_receipt(&b.bank,&b.activation,&r,1,now()).is_err(),"{mode}");}let mut r=cash(&b);r.data["availableAdvance"]=json!(1000);r.data["buyingPower"]=json!(2000);let budget=Budget::from_receipt(&b.bank,&b.activation,&r,1,now()).unwrap();assert_eq!(budget.available_gross_cash(),1000*UNIT);}
#[test]fn no_live_quotes_are_retired_or_real_reserved_cash_freed_by_hint_selection(){let f=counterexample();let b=admission_bank_mode(&f,true);let reserved=b.bank.engine().wallet.reserved().unwrap();assert!(reserved>0);let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();assert_eq!(budget.available_gross_cash(),1000*UNIT-reserved);let h=hint(&f,&b,&budget,&review(&f,0,None,None));let before=b.bank.engine().report().unwrap();assert!(b.bank.engine().order_records().iter().any(|q|q["retired"]==false));let mut fair=Fairness::new(8).unwrap();select_hints(&b.bank,&budget,&mut fair,vec![h],now()).unwrap();assert_eq!(before,b.bank.engine().report().unwrap());assert_eq!(b.bank.engine().wallet.reserved().unwrap(),reserved);let mut quiet=admission_bank(&f);let a=admit_fixture(&f,&quiet).unwrap().unwrap();quiet.bank.accept("actual-reserve",1,a.reserve_event()).unwrap();assert!(Budget::from_receipt(&quiet.bank,&quiet.activation,&cash(&quiet),1,now()).is_err(),"actual unresolved native package blocks new allocation");assert!(quiet.bank.engine().wallet.reserved().unwrap()>0);}
#[test]fn actual_completed_whole_unwind_uses_zero_funding_separate_cash_gain_tier(){let mut f=counterexample();let mut b=admission_bank(&f);let id=complete_real_session_package(&f,&mut b);profitable_unwind_books(&mut f,&mut b);let c=certified(&f);let plan=package_portfolio::whole_unwind(&b.bank,&b.activation,&c,&id,&f.policy,b.activation.entry_until_ms).unwrap().unwrap();let mut r=cash(&b);r.request_started_at=daily_windows::iso(f.policy.now_ms).unwrap();r.received_at=r.request_started_at.clone();let budget=Budget::from_receipt(&b.bank,&b.activation,&r,1,f.policy.now_ms).unwrap();let costs=review(&f,0,None,None);let e=Eligible::portfolio(&b.bank,&plan,&budget,&costs,f.policy.now_ms).unwrap();let mut fair=Fairness::new(8).unwrap();let(s,d)=select_plans(&b.bank,&budget,&mut fair,vec![e],f.policy.now_ms).unwrap();assert!(s.is_some());assert_eq!(d.full_gross_funding_units,Some(0));assert_eq!(d.minimum_incremental_gain_units,Some(UNIT));assert_eq!(d.objective,Some(Objective::CoveredUnwindStatewiseCashGain));assert!(!d.execution_authority);}
#[test]fn equal_capital_scores_rotate_without_assuming_unknown_horizons_equal(){let f=counterexample();let b=admission_bank(&f);let other=variant(&f,"other-reviewed-source");let budget=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();let mut fair=Fairness::new(8).unwrap();let mut selected=vec![];for _ in 0..2{let(_,d)=select_hints(&b.bank,&budget,&mut fair,vec![hint(&f,&b,&budget,&review(&f,0,None,None)),hint(&other,&b,&budget,&review(&other,0,None,None))],now()).unwrap();assert!(!d.fairness_override);assert_eq!(d.objective,Some(Objective::CapitalEfficiencyOnly));selected.push(d.selected_key);}assert_ne!(selected[0],selected[1]);}
#[test]fn fairness_cannot_promote_over_budget_duplicate_oversized_or_stale_head_inputs(){let f=counterexample();let mut b=admission_bank(&f);let full=Budget::from_receipt(&b.bank,&b.activation,&cash(&b),1,now()).unwrap();let h=hint(&f,&b,&full,&review(&f,0,None,None));let mut low=cash(&b);low.data=json!({"balance":1,"availableAdvance":0,"buyingPower":1});let low=Budget::from_receipt(&b.bank,&b.activation,&low,1,now()).unwrap();let mut fair=Fairness::new(1).unwrap();let(s,d)=select_hints(&b.bank,&low,&mut fair,vec![h],now()).unwrap();assert!(s.is_none());assert_eq!(d.deferred.values().next().unwrap(),"full_gross_cash");let duplicates=(0..2).map(|_|hint(&f,&b,&full,&review(&f,0,None,None))).collect();assert!(select_hints(&b.bank,&full,&mut fair,duplicates,now()).is_err());let too_many=(0..33).map(|_|hint(&f,&b,&full,&review(&f,0,None,None))).collect();assert!(select_hints(&b.bank,&full,&mut fair,too_many,now()).is_err());let h=hint(&f,&b,&full,&review(&f,0,None,None));b.bank.accept("changed-bank",1,&json!({"type":"tick","receivedAt":AT})).unwrap();assert!(select_hints(&b.bank,&full,&mut fair,vec![h],now()).is_err());}
fn review_input(f:&Fixture)->ReviewInput{ReviewInput{certificate_sha256:certificate_sha256(&f.certs[0]).unwrap(),risk_group:"operator-reviewed-component".into(),write_cost_units:0,inventory_risk_units:0,holding_horizon_ms:None,comparable_group:None,expires_at_ms:now()+60000,source_sha256:"a".repeat(64)}}
#[test]fn pinned_settings_empty_or_missing_review_never_manufactures_default_costs(){let f=counterexample();let input=review_input(&f);let empty=Settings{reviews:vec![],trusted_review_sha256:BTreeSet::new(),maximum_wait:8};empty.validate().unwrap();assert!(empty.costs_for(&input.certificate_sha256,now()).is_none());let settings=Settings{reviews:vec![input.clone()],trusted_review_sha256:[ReviewedCosts::digest(&input).unwrap()].into(),maximum_wait:8};settings.validate().unwrap();assert!(settings.costs_for(&input.certificate_sha256,now()).is_some());assert!(settings.costs_for(&"b".repeat(64),now()).is_none());assert!(settings.costs_for(&input.certificate_sha256,input.expires_at_ms).is_none());assert!(settings.costs_for(&input.certificate_sha256,input.expires_at_ms+1).is_none());let copy:Settings=serde_json::from_value(serde_json::to_value(&settings).unwrap()).unwrap();copy.validate().unwrap();assert!(copy.costs_for(&input.certificate_sha256,now()).is_some());}
#[test]fn all_configured_reviews_require_exact_unique_certificate_and_allowlist_binding(){let f=counterexample();let input=review_input(&f);let good=Settings{reviews:vec![input.clone()],trusted_review_sha256:[ReviewedCosts::digest(&input).unwrap()].into(),maximum_wait:8};for mode in ["unapproved","duplicate","changed_cost","changed_certificate","unused_trust","zero_wait","large_wait","many"]{let mut s=good.clone();match mode{"unapproved"=>s.trusted_review_sha256.clear(),"duplicate"=>s.reviews.push(input.clone()),"changed_cost"=>s.reviews[0].inventory_risk_units=1,"changed_certificate"=>s.reviews[0].certificate_sha256="b".repeat(64),"unused_trust"=>{s.trusted_review_sha256.insert("c".repeat(64));},"zero_wait"=>s.maximum_wait=0,"large_wait"=>s.maximum_wait=33,_=>s.reviews=(0..33).map(|_|input.clone()).collect()}assert!(s.validate().is_err(),"{mode}");assert!(s.costs_for(&input.certificate_sha256,now()).is_none(),"{mode}");}}
#[test]fn settings_reject_negative_or_ambiguous_review_even_with_its_digest_and_never_partially_approves(){let f=counterexample();let first=review_input(&f);for mode in ["negative","horizon_without_group","group_without_horizon","expired_zero","source","certificate"]{let mut second=first.clone();second.certificate_sha256="b".repeat(64);match mode{"negative"=>second.write_cost_units=-1,"horizon_without_group"=>second.holding_horizon_ms=Some(1000),"group_without_horizon"=>second.comparable_group=Some("group".into()),"expired_zero"=>second.expires_at_ms=0,"source"=>second.source_sha256="not-source".into(),_=>second.certificate_sha256="bad-cert".into()}let trusted=[ReviewedCosts::digest(&first).unwrap(),ReviewedCosts::digest(&second).unwrap()].into();let s=Settings{reviews:vec![first.clone(),second],trusted_review_sha256:trusted,maximum_wait:8};assert!(s.validate().is_err(),"{mode}");assert!(s.costs_for(&first.certificate_sha256,now()).is_none(),"{mode}");}}
#[test]fn serde_config_requires_explicit_cost_review_fields_and_rejects_unknown_switches(){let f=counterexample();let input=review_input(&f);let s=Settings{reviews:vec![input.clone()],trusted_review_sha256:[ReviewedCosts::digest(&input).unwrap()].into(),maximum_wait:8};for field in ["reviews","trustedReviewSha256","maximumWait"]{let mut v=serde_json::to_value(&s).unwrap();v.as_object_mut().unwrap().remove(field);assert!(serde_json::from_value::<Settings>(v).is_err(),"{field}");}for field in ["writeCostUnits","inventoryRiskUnits","sourceSha256"]{let mut v=serde_json::to_value(&s).unwrap();v["reviews"][0].as_object_mut().unwrap().remove(field);assert!(serde_json::from_value::<Settings>(v).is_err(),"{field}");}let mut v=serde_json::to_value(&s).unwrap();v["autoApproveDiscovered"]=json!(true);assert!(serde_json::from_value::<Settings>(v).is_err());}
